	@Test
	void cancellationInsideCandidateLoopStopsFurtherConditionEvaluation() throws Exception {
		AtomicReference<TestTimeLimitIteration> timeoutReference = new AtomicReference<>();
		AtomicReference<Throwable> outcome = new AtomicReference<>();
		AtomicInteger conditionCalls = new AtomicInteger();
		TrackingIteration leftIteration = new TrackingIteration(List.of(EmptyBindingSet.getInstance()), null, null,
				null);
		TrackingIteration rightIteration = new TrackingIteration(
				List.of(EmptyBindingSet.getInstance(), EmptyBindingSet.getInstance()), null, null, null);

		QueryEvaluationStep left = bindings -> leftIteration;
		QueryEvaluationStep right = bindings -> rightIteration;
		QueryValueEvaluationStep condition = bindings -> {
			if (conditionCalls.incrementAndGet() == 1) {
				timeoutReference.get().interrupt();
			}
			return BooleanLiteral.FALSE;
		};
		MaterializedReplayJoinIterator replay = new MaterializedReplayJoinIterator(left, right, condition,
				EmptyBindingSet.getInstance(), false);
		TestTimeLimitIteration timeout = new TestTimeLimitIteration(replay, LONG_TIME_LIMIT_MILLIS);
		timeoutReference.set(timeout);
		Thread worker = startWorker(timeout, outcome);

		try {
			awaitWorker(worker);
		} finally {
			timeout.close();
			awaitWorker(worker);
		}

		assertInstanceOf(TestTimeoutException.class, outcome.get());
		assertEquals(1, conditionCalls.get(), "cancellation must stop the candidate loop before its next condition");
		assertEquals(1, leftIteration.closeCalls(), "the left iterator must close exactly once");
		assertEquals(1, rightIteration.closeCalls(), "the right iterator must close exactly once");
	}

